  postAiFeedback: {
    parameters: {
      query?: never
      header?: never
      path?: never
      cookie?: never
    }
    requestBody?: never
    responses: {
      /** @description 인공지능 피드백 결과입니다. */
      200: {
        headers: {
          [name: string]: unknown
        }
        content: {
          "application/json": {
            improvements: string[]
            nextAction: string
            score: number
            scoreRange: [number, number]
            strengths: string[]
            summary: string
          }
        }
      }
      /** @description 요청이 올바르지 않습니다. */
      400: {
        headers: {
          [name: string]: unknown
        }
        content: {
          "application/json": {
            /** @constant */
            code: "invalid-request"
            message: string
          }
        }
      }
      /** @description 로그인이 필요합니다. */
      401: {
        headers: {
          [name: string]: unknown
        }
        content: {
          "application/json": {
            /** @constant */
            code: "unauthorized"
            message: string
          }
        }
      }
      /** @description 레슨, 피드백 스텝 또는 답변을 찾을 수 없습니다. */
      404: {
        headers: {
          [name: string]: unknown
        }
        content: {
          "application/json":
            | {
                /** @constant */
                code: "lesson-not-found"
                /** @constant */
                message: "레슨을 찾을 수 없습니다."
                lessonId: string
              }
            | {
                /** @constant */
                code: "answer-not-found"
                /** @constant */
                message: "답변을 찾을 수 없습니다."
              }
            | {
                /** @constant */
                code: "feedback-step-not-found"
                /** @constant */
                message: "피드백 스텝을 찾을 수 없습니다."
              }
        }
      }
      /** @description 피드백 재시도 한도를 초과했습니다. */
      429: {
        headers: {
          [name: string]: unknown
        }
        content: {
          "application/json": {
            /** @constant */
            code: "feedback-retry-limit-exceeded"
            /** @constant */
            message: "피드백 재시도 한도를 초과했습니다."
          }
        }
      }
      /** @description 콘텐츠 시드가 올바르지 않습니다. */
      500: {
        headers: {
          [name: string]: unknown
        }
        content: {
          "application/json": {
            /** @constant */
            code: "invalid-content-seed"
            message: string
            lessonId?: string
          }
        }
      }
      /** @description 인공지능 피드백 또는 데이터베이스를 사용할 수 없습니다. */
      503: {
        headers: {
          [name: string]: unknown
        }
        content: {
          "application/json":
            | {
                /** @constant */
                code: "ai-feedback-unavailable"
                /** @constant */
                message: "인공지능 피드백을 사용할 수 없습니다."
              }
            | {
                /** @constant */
                code: "database-unavailable"
                /** @constant */
                message: "데이터베이스를 사용할 수 없습니다."
              }
        }
      }
    }
  }
